                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            )}

            {currentLesson && lessonAttachments[currentLesson.id] && lessonAttachments[currentLesson.id].length > 0 && (() => {
              const atts = lessonAttachments[currentLesson.id];
              const lectures = atts.filter((a: any) => a.category === 'lecture');
              const materials = atts.filter((a: any) => a.category === 'material');
              const renderFiles = (files: typeof atts) => (
                <div className="grid gap-3 sm:grid-cols-2">
                  {files.map((att: any) => {
                    const Icon = getFileIcon(att.file_type);
                    const color = getFileColor(att.file_type);
                    return (
                      <button key={att.id} onClick={() => setPreviewFile({ url: att.file_url, name: att.name, type: att.file_type })} className="flex items-center gap-3 p-4 rounded-xl border border-border bg-card hover:bg-secondary/50 transition-colors group text-left">
                        <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 ${color}`}><Icon className="w-5 h-5" /></div>
                        <div className="flex-1 min-w-0"><p className="text-sm font-medium truncate">{att.name}</p><p className="text-xs text-muted-foreground">{att.file_type?.toUpperCase()} {att.file_size ? `• ${formatSize(att.file_size)}` : ''}</p></div>
                        <Eye className="w-4 h-4 text-muted-foreground group-hover:text-primary transition-colors shrink-0" />
                      </button>
                    );
                  })}
                </div>
              );
              return (
                <div className="mt-8 space-y-6 animate-fade-in">
                  {lectures.length > 0 && <div><h3 className="text-sm font-semibold text-muted-foreground uppercase tracking-wider mb-3">📄 Лекции</h3>{renderFiles(lectures)}</div>}
                  {materials.length > 0 && <div><h3 className="text-sm font-semibold text-muted-foreground uppercase tracking-wider mb-3">📎 Методические материалы</h3>{renderFiles(materials)}</div>}
                </div>
              );
            })()}

            <div className="flex items-center justify-between mt-12 pt-6 border-t border-border">
              <Button variant="outline" onClick={goToPrevLesson} disabled={currentLessonIndex === 0} className="gap-2"><ChevronLeft className="w-4 h-4" />Предыдущий</Button>
              {currentLessonIndex < lessons.length - 1 ? <Button onClick={goToNextLesson} className="gap-2 btn-gradient">Следующий<ChevronRight className="w-4 h-4" /></Button>
              : !embedded ? (fromStore ? <Button onClick={navigateBack} className="gap-2"><ArrowLeft className="w-4 h-4" />Назад в магазин</Button>
                : <Button onClick={navigateToEditor} className="gap-2"><Edit className="w-4 h-4" />Вернуться в редактор</Button>) : null}
            </div>
          </div>
        </ScrollArea>
      </main>
      {previewFile && <FilePreviewDialog open={!!previewFile} onOpenChange={open => !open && setPreviewFile(null)} fileUrl={previewFile.url} fileName={previewFile.name} fileType={previewFile.type} allowDownload={course?.allow_materials_download !== false} />}
    </div>
  );
}

import { useState, useEffect, useRef } from "react";
import { useParams, useNavigate, useSearchParams } from "react-router-dom";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { getAdminAwareBackPath, getCourseDetailsPath } from "@/lib/utils";
import { orderCourseLessons } from "@/lib/courseLessonOrder";
import { usePlatformHomeworkTaskProof } from "@/hooks/usePlatformHomeworkTaskProof";

export interface Lesson {
  id: string;
  course_id?: string | null;
  title: string;
  type: string;
  content?: string | null;
  order_index: number;
  module_id?: string | null;
  test_questions_count?: number | null;
  is_locked?: boolean;
}

export interface Course {
  id: string;
  organization_id?: string | null;
  title: string;
  description: string | null;
  is_published: boolean;
  allow_materials_download?: boolean;
}

export interface TestQuestion {
  id: string;
  question: string;
  options: unknown;
  order_index: number;
  explanation?: string | null;
  image_url?: string | null;
}

export interface UseCoursePreviewOptions {
  courseIdOverride?: string;
  embedded?: boolean;
  onNavigateBack?: () => void;
  onNavigateToEditor?: () => void;
}

interface CoursePreviewData {
  course: Course | null;
  lessons: Lesson[];
  lessonAttachments: Record<string, any[]>;
  courseDocuments: any[];
}

const coursePreviewKey = (courseId?: string) => ['coursePreview', courseId] as const;
const testQuestionsKey = (lessonId?: string, userId?: string) => ['testQuestions', lessonId, userId] as const;

async function fetchLessonContent(lessonId: string): Promise<string | null> {
  const { data, error } = await supabase
    .from('lessons').select('content').eq('id', lessonId).maybeSingle();
  if (error) throw error;
  if (!data) throw new Error('Lesson content is unavailable');
  return data.content;
}

async function fetchCoursePreviewData(courseId: string): Promise<CoursePreviewData> {
  const [{ data: courseData, error: courseError }, { data: lessonsData, error: lessonsError }, { data: docsData }, modulesResult] = await Promise.all([
    supabase.from('courses').select('*').eq('id', courseId).single(),
    // PERF: skip heavy `content` column for the list; fetched per-lesson on open.
    supabase
      .from('lessons')
      .select('id, course_id, title, type, order_index, module_id, is_locked, test_passing_score, test_questions_to_show, test_questions_count')
      .eq('course_id', courseId)
      .order('order_index'),
    supabase.from('course_documents').select('*').eq('course_id', courseId).order('created_at'),
    supabase.from('course_modules').select('id, order_index').eq('course_id', courseId).order('order_index'),
  ]);

  if (courseError) throw courseError;
  if (lessonsError) throw lessonsError;
  if (modulesResult.error) throw modulesResult.error;

  const lessons = orderCourseLessons((lessonsData || []) as Lesson[], modulesResult.data || []);
  let lessonAttachments: Record<string, any[]> = {};

  if (lessons.length > 0) {
    const lessonIds = lessons.map(l => l.id);
    const { data: attData } = await supabase
      .from('lesson_attachments')
      .select('*')
      .in('lesson_id', lessonIds)
      .order('order_index');
    if (attData) {
      for (const a of attData) {
        if (!lessonAttachments[a.lesson_id]) lessonAttachments[a.lesson_id] = [];
        lessonAttachments[a.lesson_id].push(a);
      }
    }
  }

  return {
    course: courseData as Course,
    lessons,
    lessonAttachments,
    courseDocuments: docsData || [],
  };
}

export function useCoursePreview(options: UseCoursePreviewOptions = {}) {
  const params = useParams();
  const courseId = options.courseIdOverride ?? params.courseId;
  const { user } = useAuth();
  const navigate = useNavigate();
  const qc = useQueryClient();
  const [searchParams] = useSearchParams();
  const fromStore = searchParams.get('from') === 'store';
  const contentRef = useRef<HTMLDivElement>(null);

  const [currentLessonIndex, setCurrentLessonIndex] = useState(0);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<string, number>>({});
  const [showDocumentsView, setShowDocumentsView] = useState(false);
  const [previewFile, setPreviewFile] = useState<{ url: string; name: string; type: string | null } | null>(null);

  const { data, isLoading } = useQuery({
    queryKey: coursePreviewKey(courseId),
    queryFn: () => fetchCoursePreviewData(courseId!),
    enabled: !!courseId && !!user,
    staleTime: 60_000,
    gcTime: 5 * 60_000,
    meta: {
      onError: () => toast.error('Ошибка загрузки курса'),
    },
  });

  const course = data?.course ?? null;
  const lessons = data?.lessons ?? [];
  const lessonAttachments = data?.lessonAttachments ?? {};
  const courseDocuments = data?.courseDocuments ?? [];

  const baseLesson = showDocumentsView ? null : lessons[currentLessonIndex];

  // Lazy load content for currently opened lesson + prefetch next.
  const currentContentQuery = useQuery({
    queryKey: ['lesson-content', baseLesson?.id],
    enabled: !!baseLesson?.id,
    staleTime: 5 * 60_000,
    queryFn: () => fetchLessonContent(baseLesson!.id),
  });
  const nextLesson = baseLesson ? lessons[currentLessonIndex + 1] : null;
  useQuery({
    queryKey: ['lesson-content', nextLesson?.id],
    enabled: !!nextLesson?.id,
    staleTime: 5 * 60_000,
    queryFn: () => fetchLessonContent(nextLesson!.id),
  });

  const currentLesson = baseLesson ? { ...baseLesson, content: baseLesson.content ?? currentContentQuery.data ?? null } as Lesson : null;
  const { scope: homeworkTaskScope, proof: homeworkTaskProof } = usePlatformHomeworkTaskProof({
    scope: { routeCourseId: courseId, course, lesson: currentLesson, actorId: user?.id },
    content: currentLesson?.content, lessonType: currentLesson?.type,
    enabled: !isLoading && !showDocumentsView && !currentContentQuery.isPending && !currentContentQuery.isError,
    contextKey: JSON.stringify(['preview', !!options.embedded]),
  });

  const { data: testQuestionsData } = useQuery({
    queryKey: testQuestionsKey(currentLesson?.id, user?.id),
    queryFn: async () => {
      const { data, error } = await supabase.rpc('get_student_test_questions', {
        p_lesson_id: currentLesson!.id,
      });
      if (error) throw error;
      return (data || []) as TestQuestion[];
    },
    enabled: !!user && !!currentLesson?.id && currentLesson.type === 'test',
    staleTime: 5 * 60_000,
  });

  const testQuestions = testQuestionsData ?? [];

  // Reset answers when test lesson changes
  useEffect(() => {
    if (currentLesson?.type === 'test') setSelectedAnswers({});
  }, [currentLesson?.id, currentLesson?.type]);

  useEffect(() => {
    if (contentRef.current) contentRef.current.scrollTo({ top: 0, behavior: 'smooth' });
  }, [currentLessonIndex]);

  const transition = (cb: () => void) => {
    setIsTransitioning(true);
    setTimeout(() => { cb(); setIsTransitioning(false); }, 300);
  };

  const goToNextLesson = () => {
    if (currentLessonIndex < lessons.length - 1) transition(() => setCurrentLessonIndex(prev => prev + 1));
  };
  const goToPrevLesson = () => {
    if (currentLessonIndex > 0) transition(() => setCurrentLessonIndex(prev => prev - 1));
  };
  const goToLesson = (index: number) => {
    if (index !== currentLessonIndex || showDocumentsView) {
      setShowDocumentsView(false);
      transition(() => setCurrentLessonIndex(index));
    }
  };
  const goToDocumentsView = () => {
    if (!showDocumentsView) transition(() => setShowDocumentsView(true));
  };

  const navigateBack = () => {
    if (options.onNavigateBack) return options.onNavigateBack();
    if (fromStore) return navigate(getAdminAwareBackPath());
    return courseId ? navigate(getCourseDetailsPath(courseId)) : navigate(getAdminAwareBackPath());
  };
  const navigateToEditor = () => {
    if (options.onNavigateToEditor) return options.onNavigateToEditor();
    return navigate(`/course-builder/${courseId}`);
  };

  // Backwards-compatible refetcher for test questions used by callers (e.g. after submit)
  const fetchTestQuestions = (lessonId: string) => {
    qc.invalidateQueries({ queryKey: testQuestionsKey(lessonId, user?.id) });
  };

  return {
    courseId, course, lessons, currentLesson, currentLessonIndex, homeworkTaskScope, homeworkTaskProof,
    loading: isLoading, isTransitioning,
    lessonContentLoading: !!baseLesson && currentContentQuery.isPending,
    lessonContentError: currentContentQuery.isError,
    reloadLessonContent: () => currentContentQuery.refetch(),
    testQuestions, selectedAnswers, setSelectedAnswers, lessonAttachments, courseDocuments,
    showDocumentsView, previewFile, setPreviewFile, contentRef, fromStore,
    goToNextLesson, goToPrevLesson, goToLesson, goToDocumentsView,
    navigateBack, navigateToEditor, fetchTestQuestions,
  };
}

import { useEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import { useAuth } from '@/hooks/useAuth';
import { supabase } from '@/integrations/supabase/client';
import { MARKETPLACE_ORG_ID } from '@/constants/marketplace';
import { captureOfflineActor, captureOfflineAuthRevision, isOfflineActorCurrent, subscribeOfflineAuthRevision } from '@/utils/courseCache';
import type { HomeworkTaskScope, VerifiedHomeworkTaskProof } from '@/components/course-learning/HomeworkTaskDescription';

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const SHA256 = /^[0-9a-f]{64}$/;
const PROOF_LEASE_MS = 30_000;
const REQUEST_TIMEOUT_MS = 10_000;

interface TaskProofOptions {
  scope: HomeworkTaskScope;
  content: string | null | undefined;
  lessonType?: string;
  enabled: boolean;
  contextKey: string;
}

// B2 is not yet in generated Database types. Keep the transport narrow, treat
// its response as unknown and validate every returned field before presentation.
interface TaskProofClient {
  rpc(name: 'get_platform_learning_task_proof', args: { p_course_id: string; p_lesson_id: string }): {
    abortSignal(signal: AbortSignal): PromiseLike<{ data: unknown; error: unknown }>;
  };
}

function matchesVerifiedResponse(data: unknown, courseId: string, lessonId: string, digest: string): data is {
  status: 'verified'; courseId: string; lessonId: string; contentSha256: string; policyId: string;
} {
  if (!data || typeof data !== 'object' || Array.isArray(data)) return false;
  const value = data as Record<string, unknown>;
  return value.status === 'verified' && value.courseId === courseId && value.lessonId === lessonId
    && typeof value.contentSha256 === 'string' && SHA256.test(value.contentSha256) && value.contentSha256 === digest
    && typeof value.policyId === 'string' && UUID.test(value.policyId);
}

/** Presentation only: never grants access, submit rights, completion or a grade. */
export function usePlatformHomeworkTaskProof({ scope, content, lessonType, enabled, contextKey }: TaskProofOptions) {
  const { user, session, loading, authError } = useAuth();
  const authEpoch = useSyncExternalStore(subscribeOfflineAuthRevision, captureOfflineAuthRevision, () => 0);
  const actorId = user?.id;
  const actorRevision = captureOfflineActor(actorId);
  const rawContent = content ?? '';
  const courseId = scope.routeCourseId;
  const lessonId = scope.lesson?.id;
  const ownerId = scope.course?.organization_id;
  const [refresh, setRefresh] = useState(0);
  const lease = useMemo(() => ({}), [
    courseId, scope.course?.id, ownerId, lessonId, scope.lesson?.course_id,
    scope.actorId, actorId, actorRevision, authEpoch, rawContent, lessonType,
    enabled, contextKey, loading, authError, session?.user.id, session?.access_token,
    user?.is_anonymous, session?.user.is_anonymous, refresh,
  ]);
  const currentLease = useRef(lease);
  currentLease.current = lease;
  const [proof, setProof] = useState<VerifiedHomeworkTaskProof | null>(null);

  const eligible = enabled && !loading && !authError && !!actorId && UUID.test(actorId)
    && user?.is_anonymous !== true && session?.user.is_anonymous !== true
    && session?.user.id === actorId && !!session?.access_token
    && scope.actorId === actorId && isOfflineActorCurrent(actorId, actorRevision)
    && !!courseId && UUID.test(courseId) && scope.course?.id === courseId
    && !!ownerId && UUID.test(ownerId) && ownerId !== MARKETPLACE_ORG_ID
    && !!lessonId && UUID.test(lessonId) && scope.lesson?.course_id === courseId
    && lessonType === 'homework';

  useEffect(() => {
    let active = true;
    const controller = new AbortController();
    let expiryTimer: ReturnType<typeof setTimeout> | undefined;
    let requestTimer: ReturnType<typeof setTimeout> | undefined;
    const current = () => active && currentLease.current === lease && !!actorId
      && isOfflineActorCurrent(actorId, actorRevision);
    setProof(null);
    if (eligible && actorId && courseId && lessonId && ownerId) {
      requestTimer = setTimeout(() => { controller.abort(); if (current()) setProof(null); }, REQUEST_TIMEOUT_MS);
      void (async () => {
        // Hash exactly the raw UTF-8 bytes coalesce(content,'') used by B2.
        // No trim, HTML parsing, sanitizing, line-ending or Unicode normalization.
        if (!globalThis.crypto?.subtle || typeof TextEncoder === 'undefined') throw new Error('No secure digest');
        const bytes = await globalThis.crypto.subtle.digest('SHA-256', new TextEncoder().encode(rawContent));
        const digest = Array.from(new Uint8Array(bytes), byte => byte.toString(16).padStart(2, '0')).join('');
        if (!current() || controller.signal.aborted) return;
        const { data, error } = await (supabase as unknown as TaskProofClient)
          .rpc('get_platform_learning_task_proof', { p_course_id: courseId, p_lesson_id: lessonId })
          .abortSignal(controller.signal);
        if (!current() || controller.signal.aborted) return;
        if (error || !matchesVerifiedResponse(data, courseId, lessonId, digest)) throw new Error('Unverified task');
        if (requestTimer) clearTimeout(requestTimer);
        setProof({ status: 'verified', courseId, lessonId, organizationId: ownerId, actorId,
          actorRevision: actorRevision!, contentSha256: digest, policyId: data.policyId,
          rawContent, lease, expiresAt: Date.now() + PROOF_LEASE_MS });
        expiryTimer = setTimeout(() => {
          if (current()) { setProof(null); setRefresh(value => value + 1); }
        }, PROOF_LEASE_MS);
      })().catch(() => { if (current()) setProof(null); });
    }
    return () => {
      active = false;
      controller.abort();
      if (requestTimer) clearTimeout(requestTimer);
      if (expiryTimer) clearTimeout(expiryTimer);
    };
  }, [lease, eligible, actorId, actorRevision, courseId, lessonId, ownerId, rawContent]);

  // Synchronous lease/content/actor checks prevent a previous render's proof
  // surviving a route, owner, loaded lesson, context, auth or raw-content change.
  const visibleProof = eligible && proof?.lease === lease && proof.rawContent === rawContent
    && proof.expiresAt > Date.now() && !!actorId && isOfflineActorCurrent(actorId, actorRevision) ? proof : null;
  return { scope: { ...scope, actorId, actorRevision, contextLease: lease }, proof: visibleProof };
}

